// syncIdleLimitHistory says when the server last refused a connection and
// since when the limit has held.
func syncIdleLimitHistory(ctx context.Context, limit models.IdleLimitStatus) string {
	var parts []string
	dates := i18n.Dates(ctx)
	if limit.FailedAt > 0 && !limit.FailedTime.IsZero() {
		parts = append(parts, i18n.T(ctx, "settings.sync.idle_limit.refused", "count", limit.FailedAt, "date", dates.LongMonthDate(limit.FailedTime.Local())))
	}
	if limit.StableAt > 0 && !limit.StableSince.IsZero() {
		parts = append(parts, i18n.N(ctx, "settings.sync.idle_limit.stable", limit.StableAt, "count", limit.StableAt, "date", dates.LongMonthDate(limit.StableSince.Local())))
	}
	return strings.Join(parts, " ")
}

